window.ZETALVX_LOCALES.entries.push(...[{"sources":["Link existing server files and folders"],"text":{"en":"Link existing server files and folders","it":"Collega file e cartelle già presenti sul server"}},{"sources":["Choose one file, a complete component folder, or a folder containing LoRA files. Linking a LoRA folder registers each compatible .safetensors separately, without copying."],"text":{"en":"Choose one file, a complete component folder, or a folder containing LoRA files. Linking a LoRA folder registers each compatible .safetensors separately, without copying.","it":"Scegli un file, la cartella completa di un componente o una cartella di LoRA. Collegando una cartella LoRA, ogni file .safetensors compatibile viene registrato separatamente, senza copiarlo."}},{"sources":["Both methods add components to the same catalog. A server link keeps original files in place; a browser upload copies them. LoRA folders are supported in both methods. Complete Diffusers repositories, VAE/encoder component folders, processors and schedulers must be linked from the server or downloaded from their source."],"text":{"en":"Both methods add components to the same catalog. A server link keeps original files in place; a browser upload copies them. LoRA folders are supported in both methods. Complete Diffusers repositories, VAE/encoder component folders, processors and schedulers must be linked from the server or downloaded from their source.","it":"Entrambi i metodi aggiungono componenti allo stesso catalogo. Il collegamento dal server mantiene i file dove sono; il caricamento dal browser li copia. Le cartelle LoRA funzionano in entrambi i metodi. Le cartelle dei repository Diffusers, VAE, encoder, processor e scheduler si collegano dal server oppure si scaricano dalla fonte."}},{"sources":["Selection"],"text":{"en":"Selection","it":"Selezione"}},{"sources":["Single file"],"text":{"en":"Single file","it":"File singolo"}},{"sources":["LoRA folder (all .safetensors)"],"text":{"en":"LoRA folder (all .safetensors)","it":"Cartella LoRA (tutti i .safetensors)"}},{"sources":["LoRA folder"],"text":{"en":"LoRA folder","it":"Cartella LoRA"}},{"sources":["Qwen3-VL text encoder file (.safetensors)"],"text":{"en":"Qwen3-VL text encoder file (.safetensors)","it":"File encoder Qwen3-VL (.safetensors)"}},{"sources":["Supported browsers can select a folder, including nested LoRA files. Up to 250 .safetensors are uploaded individually; other files are ignored. Keep this page open."],"text":{"en":"Supported browsers can select a folder, including nested LoRA files. Up to 250 .safetensors are uploaded individually; other files are ignored. Keep this page open.","it":"Nei browser compatibili puoi selezionare una cartella, incluse sottocartelle. Vengono caricati fino a 250 file .safetensors singolarmente; gli altri sono ignorati. Tieni aperta la pagina."}},{"sources":["I verified Qwen Image 2.1 compatibility and the files' licences."],"text":{"en":"I verified Qwen Image 2.1 compatibility and the files' licences.","it":"Ho verificato la compatibilità con Qwen Image 2.1 e le licenze dei file."}},{"sources":["Keep this page open while browser uploads run. Individual files (including each file in a LoRA folder) are added to Available components after validation. File and folder imports never treat a LoRA directory itself as an adapter."],"text":{"en":"Keep this page open while browser uploads run. Individual files (including each file in a LoRA folder) are added to Available components after validation. File and folder imports never treat a LoRA directory itself as an adapter.","it":"Tieni aperta questa pagina durante il caricamento. Ogni file, anche da una cartella LoRA, viene aggiunto ai componenti disponibili dopo la verifica. Le cartelle LoRA non vengono mai usate direttamente come adapter."}},{"sources":["Choose a model file or folder first."],"text":{"en":"Choose a model file or folder first.","it":"Seleziona prima un file o una cartella del modello."}},{"sources":["Checking server files…"],"text":{"en":"Checking server files…","it":"Verifica dei file sul server…"}},{"sources":["File or component linked without copying. It is now available in My models."],"text":{"en":"File or component linked without copying. It is now available in My models.","it":"File o componente collegato senza copiarlo. È disponibile in I miei modelli."}},{"sources":["No .safetensors files found in this folder."],"text":{"en":"No .safetensors files found in this folder.","it":"Nessun file .safetensors trovato nella cartella."}},{"sources":["Choose a LoRA folder first."],"text":{"en":"Choose a LoRA folder first.","it":"Seleziona prima una cartella LoRA."}},{"sources":["Folder upload is available only for LoRA files."],"text":{"en":"Folder upload is available only for LoRA files.","it":"Il caricamento delle cartelle è disponibile solo per le LoRA."}},{"sources":["Upload at most 250 LoRA files per folder."],"text":{"en":"Upload at most 250 LoRA files per folder.","it":"Carica al massimo 250 file LoRA per cartella."}},{"sources":["Confirm source compatibility and licence before uploading."],"text":{"en":"Confirm source compatibility and licence before uploading.","it":"Conferma compatibilità e licenza prima del caricamento."}},{"sources":["LoRA folder: {linked} file(s) linked, {failed} rejected. Each LoRA appears separately in Available components."],"text":{"en":"LoRA folder: {linked} file(s) linked, {failed} rejected. Each LoRA appears separately in Available components.","it":"Cartella LoRA: {linked} file collegati, {failed} rifiutati. Ogni LoRA compare separatamente nei componenti disponibili."}},{"sources":["LoRA folder: {ok} uploaded, {failed} failed."],"text":{"en":"LoRA folder: {ok} uploaded, {failed} failed.","it":"Cartella LoRA: {ok} caricati, {failed} non riusciti."}}]);

